package com.craftdistrict.block;

import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

/** Generated by tools/generate_fire_fixtures.py; structural envelopes, part, facing. */
final class FireFixtureShapes {
    private static final VoxelShape[][][] SHAPES = {
        {
            rotations(Shapes.or(
                Block.box(2, 2, 13.875, 14, 14, 16)).optimize())
        },
        {
            rotations(Shapes.or(
                Block.box(0.5, 0.5, 13.75, 16, 16, 16)).optimize()),
            rotations(Shapes.or(
                Block.box(0, 0.5, 13.75, 15.5, 16, 16)).optimize()),
            rotations(Shapes.or(
                Block.box(0.5, 0, 13.75, 16, 15.5, 16)).optimize()),
            rotations(Shapes.or(
                Block.box(0, 0, 13.75, 15.5, 15.5, 16)).optimize())
        },
        {
            rotations(Shapes.or(
                Block.box(0, 7.75, 3.625, 16, 8.75, 12.375),
                Block.box(0, 2.5, 4.375, 16, 3, 11.625),
                Block.box(3, 0, 3.625, 4.5, 7.75, 5.125),
                Block.box(3, 0, 10.875, 4.5, 7.75, 12.375)).optimize()),
            rotations(Shapes.or(
                Block.box(0, 7.75, 3.625, 16, 8.75, 12.375),
                Block.box(0, 2.5, 4.375, 16, 3, 11.625),
                Block.box(11.5, 0, 3.625, 13.0, 7.75, 5.125),
                Block.box(11.5, 0, 10.875, 13.0, 7.75, 12.375)).optimize())
        },
        {
            rotations(Shapes.or(
                Block.box(2, 2, 12.5, 14, 14, 16),
                Block.box(11.75, 6, 12, 12.5, 9, 12.5)).optimize())
        }
    };
    private FireFixtureShapes() { }

    static VoxelShape get(int decoration, int part, BlockState state) {
        int turn = switch (state.getValue(BlockStateProperties.HORIZONTAL_FACING)) {
            case EAST -> 1;
            case SOUTH -> 2;
            case WEST -> 3;
            default -> 0;
        };
        return SHAPES[decoration][part][turn];
    }

    private static VoxelShape[] rotations(VoxelShape north) {
        VoxelShape[] result = new VoxelShape[4];
        result[0] = north;
        for (int turn = 1; turn < 4; turn++) {
            VoxelShape rotated = Shapes.empty();
            for (AABB box : result[turn-1].toAabbs()) {
                rotated = Shapes.or(rotated, Shapes.box(1-box.maxZ,box.minY,box.minX,1-box.minZ,box.maxY,box.maxX));
            }
            result[turn] = rotated.optimize();
        }
        return result;
    }
}
